/* Public QEMU-only RSA vectors, generated by the host software MFi provider. */
#ifndef MHI2Q_SOFTWARE_MFI_FIXTURE_H
#define MHI2Q_SOFTWARE_MFI_FIXTURE_H
#include <stddef.h>
#include <stdint.h>
#include <string.h>

#define MFIQ_MAX_CERT 1280u
#define MFIQ_MAX_CASES 8u
#define MFIQ_MAX_FILE (12u + MFIQ_MAX_CERT + MFIQ_MAX_CASES * 148u)
struct mfiq_case { uint8_t digest[20], signature[128]; };
struct mfiq_fixture {
    size_t certificate_length, case_count;
    uint8_t certificate[MFIQ_MAX_CERT];
    struct mfiq_case cases[MFIQ_MAX_CASES];
};
static int mfiq_decode(struct mfiq_fixture *result, const uint8_t *data, size_t size)
{
    static const uint8_t magic[8] = {'M','F','I','Q',1,0,0,0};
    static const char subject[] = "NOT_A_REAL_MFI_IDENTITY";
    size_t cert, count, i, j;
    int marked = 0;
    if (!result || !data || size < 12 || size > MFIQ_MAX_FILE ||
        memcmp(data, magic, sizeof(magic))) return -1;
    cert = (size_t)data[8] * 256u + data[9];
    count = (size_t)data[10] * 256u + data[11];
    if (!cert || cert > MFIQ_MAX_CERT || !count || count > MFIQ_MAX_CASES ||
        size != 12u + cert + count * 148u) return -1;
    for (i = 0; i + sizeof(subject) - 1 <= cert; ++i)
        if (!memcmp(data + 12 + i, subject, sizeof(subject) - 1)) marked = 1;
    if (!marked) return -1;
    /* Validate the complete input before changing the output state. */
    for (i = 0; i < count; ++i)
        for (j = 0; j < i; ++j)
            if (!memcmp(data + 12 + cert + i * 148,
                        data + 12 + cert + j * 148, 20)) return -1;
    memset(result, 0, sizeof(*result));
    result->certificate_length = cert;
    result->case_count = count;
    memcpy(result->certificate, data + 12, cert);
    for (i = 0; i < count; ++i) {
        memcpy(result->cases[i].digest, data + 12 + cert + i * 148, 20);
        memcpy(result->cases[i].signature, data + 32 + cert + i * 148, 128);
    }
    return 0;
}
static int mfiq_signature(const struct mfiq_fixture *fixture,
                          const uint8_t digest[20], uint8_t signature[128])
{
    size_t i;
    if (!fixture || !digest || !signature || !fixture->case_count ||
        fixture->case_count > MFIQ_MAX_CASES) return -1;
    for (i = 0; i < fixture->case_count; ++i)
        if (!memcmp(fixture->cases[i].digest, digest, 20)) {
            memcpy(signature, fixture->cases[i].signature, 128);
            return 0;
        }
    return -1;
}
#endif
